// Generated by build-pages.py. Cache only this portfolio's first film.
const CACHE_PREFIX = 'cognitive-dissonance-first-film-';
const CACHE_NAME = CACHE_PREFIX + '__VIDEO_HASH__';
const FIRST_VIDEO = new URL('__VIDEO_PATH__', self.registration.scope).href;
let warming;

self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

async function warmFirstVideo() {
  if (warming) return warming;
  warming = (async () => {
    const cache = await caches.open(CACHE_NAME);
    if (await cache.match(FIRST_VIDEO)) return;
    const response = await fetch(FIRST_VIDEO, { cache: 'reload', priority: 'low' });
    if (response.status !== 200) throw new Error('First-film download did not return a complete file');
    await cache.put(FIRST_VIDEO, response);
  })();
  try { await warming; } finally { warming = undefined; }
}

self.addEventListener('message', event => {
  if (event.data?.type !== 'PREFETCH_FIRST_VIDEO') return;
  // The worker keeps the download alive when the visitor leaves the home page.
  // Storage/network failures never block the normal media player.
  event.waitUntil(warmFirstVideo().catch(() => {}));
});

async function serveFirstVideo(request) {
  let cached;
  try { cached = await (await caches.open(CACHE_NAME)).match(FIRST_VIDEO); }
  catch { return fetch(request); }
  // A visit before prefetch completes streams normally instead of waiting for
  // the whole background download. Later requests can use the completed cache.
  if (!cached) return fetch(request);
  const range = request.headers.get('Range');
  if (!range) return cached;
  const validator = request.headers.get('If-Range');
  if (validator && validator !== cached.headers.get('ETag') && validator !== cached.headers.get('Last-Modified')) return fetch(request);
  const match = /^bytes=(\d*)-(\d*)$/.exec(range);
  if (!match || (!match[1] && !match[2])) return fetch(request);
  const blob = await cached.blob();
  const size = blob.size;
  let start;
  let end;
  if (!match[1]) {
    const suffix = Number(match[2]);
    start = Math.max(0, size - suffix);
    end = size - 1;
    if (suffix === 0) start = size;
  } else {
    start = Number(match[1]);
    end = match[2] ? Math.min(Number(match[2]), size - 1) : size - 1;
  }
  if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start >= size || start > end) {
    return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}`, 'Accept-Ranges': 'bytes' } });
  }
  const headers = new Headers(cached.headers);
  headers.delete('Content-Encoding');
  headers.delete('Transfer-Encoding');
  headers.set('Content-Type', 'video/mp4');
  headers.set('Accept-Ranges', 'bytes');
  headers.set('Content-Range', `bytes ${start}-${end}/${size}`);
  headers.set('Content-Length', String(end - start + 1));
  return new Response(blob.slice(start, end + 1, 'video/mp4'), { status: 206, headers });
}

self.addEventListener('fetch', event => {
  if (event.request.method === 'GET' && event.request.url === FIRST_VIDEO) {
    event.respondWith(serveFirstVideo(event.request));
  }
});
